            count += 1
        state['pending'] = pending[index:]
        state['count'] += count

    def finish(state):
        if state['status'] != 'open':
            return
        if len(state['pending']) != 0:
            state['pending'] = []
            state['status'] = 'error'
        else:
            state['status'] = 'finished'

    def reset(state):
        state['count'] = 0
        state['status'] = 'open'
        state['pending'] = []

    state = {'count': 0, 'status': 'open', 'pending': []}
    for event in context['events']:
        operation = event['op']
        if operation == 'feed':
            feed(state, event['bytes'])
        elif operation == 'finish':
            finish(state)
        elif operation == 'reset':
            reset(state)
    return {'count': state['count'], 'status': state['status']}
